//! The bundled asset source.
//!
//! GPUI reaches assets by path through an [`AssetSource`], which usually means
//! a folder next to the binary. Lumen's are compiled in instead, for the same
//! reason the font is (AD-14): the launcher is a single executable, and an
//! icon that can go missing between install and first run is an icon that
//! will.
//!
//! The table is explicit rather than generated by a macro over the folder. A
//! typo in a path then fails a test in this file instead of drawing nothing at
//! runtime, and the set is small enough that the table is the documentation.

use std::borrow::Cow;

use anyhow::Result;
use gpui::{AssetSource, SharedString};

/// Everything compiled into the binary, by the path GPUI asks for.
const ASSETS: &[(&str, &[u8])] = &[
    (
        "icons/application.svg",
        include_bytes!("../../../assets/icons/application.svg"),
    ),
    (
        "icons/calculator.svg",
        include_bytes!("../../../assets/icons/calculator.svg"),
    ),
    (
        "icons/clipboard.svg",
        include_bytes!("../../../assets/icons/clipboard.svg"),
    ),
    (
        "icons/command.svg",
        include_bytes!("../../../assets/icons/command.svg"),
    ),
    (
        "icons/file.svg",
        include_bytes!("../../../assets/icons/file.svg"),
    ),
    (
        "icons/link.svg",
        include_bytes!("../../../assets/icons/link.svg"),
    ),
    (
        "icons/script.svg",
        include_bytes!("../../../assets/icons/script.svg"),
    ),
    (
        "icons/image.svg",
        include_bytes!("../../../assets/icons/image.svg"),
    ),
    (
        "icons/text.svg",
        include_bytes!("../../../assets/icons/text.svg"),
    ),
    (
        "icons/snippet.svg",
        include_bytes!("../../../assets/icons/snippet.svg"),
    ),
    (
        "icons/window.svg",
        include_bytes!("../../../assets/icons/window.svg"),
    ),
    (
        "icons/timer.svg",
        include_bytes!("../../../assets/icons/timer.svg"),
    ),
    (
        "icons/currency.svg",
        include_bytes!("../../../assets/icons/currency.svg"),
    ),
];

pub struct Assets;

impl AssetSource for Assets {
    fn load(&self, path: &str) -> Result<Option<Cow<'static, [u8]>>> {
        Ok(ASSETS
            .iter()
            .find(|(name, _)| *name == path)
            .map(|(_, bytes)| Cow::Borrowed(*bytes)))
    }

    fn list(&self, path: &str) -> Result<Vec<SharedString>> {
        Ok(ASSETS
            .iter()
            .filter(|(name, _)| name.starts_with(path))
            .map(|(name, _)| SharedString::from(*name))
            .collect())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use lumen_core::Kind;

    /// Every glyph the row renderer can ask for has to be in the table, or the
    /// row draws an empty square and nothing says why.
    #[test]
    fn every_kind_resolves_to_an_asset_that_exists() {
        for kind in [
            Kind::Application,
            Kind::Command,
            Kind::Calculation,
            Kind::Script,
            Kind::Snippet,
            Kind::Clipboard,
            Kind::Window,
            Kind::File,
            Kind::Quicklink,
            Kind::Timer,
        ] {
            let path = crate::icons::glyph(kind);
            assert!(
                Assets.load(path).unwrap().is_some(),
                "{kind:?} asks for {path}, which is not bundled"
            );
        }
    }

    /// Each icon is drawn on a 20-unit grid. One drawn on a different one would
    /// be a different size in the same square, which is the whole thing F2's
    /// "optically aligned" is asking for.
    #[test]
    fn every_icon_is_drawn_on_the_same_grid() {
        for (name, bytes) in ASSETS {
            let source = std::str::from_utf8(bytes).unwrap();
            assert!(
                source.contains("viewBox=\"0 0 20 20\""),
                "{name} is not on the 20-unit grid"
            );
            assert!(
                source.contains("stroke-width=\"1.5\""),
                "{name} does not use the 1.5 stroke"
            );
            assert!(
                source.contains("stroke=\"currentColor\""),
                "{name} does not take its colour from the theme"
            );
        }
    }

    #[test]
    fn an_unknown_path_is_absent_rather_than_an_error() {
        assert!(Assets.load("icons/nothing.svg").unwrap().is_none());
    }

    #[test]
    fn the_icons_can_be_listed() {
        assert_eq!(Assets.list("icons/").unwrap().len(), ASSETS.len());
    }
}
